SELECT CAST(NULL AS varchar) AS account_code, CAST(NULL AS varchar) AS account_name, x.act04_ast_class_tree_nm AS ast_class_tree_name, CAST(NULL AS numeric) AS dr_today_bal_amt, CAST(NULL AS numeric) AS cr_today_bal_amt, x.act04_dr_today_diff_amt AS dr_today_diff_amt, CAST(NULL AS varchar) AS check_code, CAST(NULL AS varchar) AS note, CAST(NULL AS varchar) AS corp_name, CAST(NULL AS varchar) AS corp_code, CAST(NULL AS varchar) AS fund_code, CAST(NULL AS varchar) AS fund_name, CAST(NULL AS numeric) AS icam_fee, CAST(NULL AS numeric) AS for_fee, CAST(NULL AS numeric) AS diff_fee FROM (
WITH book AS ( WITH book1 AS ( SELECT '1' seq , ast09_book.* FROM ast09_book WHERE ast09_company_id = #{companyId} AND (ast09_ast_class_tree_id, ast09_keep_account_id, ast09_hold_date) IN ( SELECT ast09_ast_class_tree_id, ast09_keep_account_id, MAX(ast09_hold_date) FROM ast09_book WHERE ast09_company_id = #{companyId} AND ast09_hold_date <= #{holdDate}
AND ast09_ast_class_tree_id = #{astClassTreeId}
AND ast09_keep_account_id = #{keepAccountId}
GROUP BY ast09_ast_class_tree_id, ast09_keep_account_id ) UNION ALL SELECT '2' seq , ast11_book_id , ast11_hold_date , ast11_ast_class_tree_id , ast11_keep_account_id , ast11_hold_qty , ast11_pur_amt , ast11_book_amt , ast11_eval_amt , ast11_eval_pl , ast11_first_pur_amt , ast11_first_pur_date , ast11_company_id , ast11_for_pur_amt , ast11_for_book_amt , ast11_for_eval_amt , ast11_for_eval_pl , ast11_fx_pl , ast11_book_end_yn , ast11_acr_int_amt , ast11_for_acr_int_amt , ast11_oci , ast11_for_oci , ast11_lock_up_period_cd , ast11_lock_up_date , ast11_lock_up_qty FROM ast11_book_close WHERE ast11_company_id = #{companyId} AND (ast11_ast_class_tree_id, ast11_keep_account_id, ast11_hold_date) IN ( SELECT ast11_ast_class_tree_id, ast11_keep_account_id, MAX(ast11_hold_date) FROM ast11_book_close WHERE ast11_company_id = #{companyId} AND ast11_hold_date < #{holdDate}
AND ast11_ast_class_tree_id = #{astClassTreeId}
AND ast11_keep_account_id = #{keepAccountId}
GROUP BY ast11_ast_class_tree_id, ast11_keep_account_id ) ) SELECT * FROM book1 WHERE (ast09_ast_class_tree_id, ast09_keep_account_id, to_char(ast09_hold_date,'yyyymmdd')||seq) IN ( SELECT ast09_ast_class_tree_id, ast09_keep_account_id, MAX(to_char(ast09_hold_date,'yyyymmdd')||seq) FROM book1 GROUP BY ast09_ast_class_tree_id, ast09_keep_account_id ) )
SELECT row_number() OVER (ORDER BY ast01_class_tree_nm) AS act04_gen_ledger_id , ast09_ast_class_tree_id AS act04_ast_class_tree_id , ast01_class_tree_nm AS act04_ast_class_tree_nm , SUM(ast09_hold_qty) AS act04_dr_today_diff_amt FROM ( SELECT ast09_ast_class_tree_id , ast01_class_tree_nm , ast09_hold_qty FROM book INNER JOIN ast01_class_tree ON ast01_class_tree_id = ast09_ast_class_tree_id WHERE ast01_item_l_class_cd = '10' /* 10:현금 및 예치금 */ AND ast01_asset_type = '1' /* 1:고유자산 */ AND ast01_item_s_class_cd NOT IN ( SELECT sys09_code FROM sys13_code_group INNER JOIN sys09_code ON sys09_code_id = sys13_code_id WHERE sys13_kind_group_cd = 'ItemSClassCode004' ) UNION ALL SELECT ast12_ast_class_tree_id , ast01_class_tree_nm , COALESCE(ast12_real_qty,0) * -1 as ast09_hold_qty FROM ast12_book_real INNER JOIN ast01_class_tree ON ast01_class_tree_id = ast12_ast_class_tree_id WHERE ast12_company_id = #{companyId} AND ast12_hold_date = #{holdDate} ) t GROUP BY ast09_ast_class_tree_id, ast01_class_tree_nm HAVING SUM(ast09_hold_qty) != 0
) x

SELECT CAST(NULL AS varchar) AS account_code, CAST(NULL AS varchar) AS account_name, CAST(NULL AS varchar) AS ast_class_tree_name, CAST(NULL AS numeric) AS dr_today_bal_amt, CAST(NULL AS numeric) AS cr_today_bal_amt, CAST(NULL AS numeric) AS dr_today_diff_amt, x.act04_check_cd AS check_code, x.act04_note AS note, CAST(NULL AS varchar) AS corp_name, CAST(NULL AS varchar) AS corp_code, CAST(NULL AS varchar) AS fund_code, CAST(NULL AS varchar) AS fund_name, CAST(NULL AS numeric) AS icam_fee, CAST(NULL AS numeric) AS for_fee, CAST(NULL AS numeric) AS diff_fee FROM (
