AND ast11_ast_class_tree_id = #{astClassTreeId}
AND ast11_keep_account_id = #{keepAccountId}
GROUP BY ast11_ast_class_tree_id, ast11_keep_account_id ) ) SELECT * FROM book1 WHERE (ast09_ast_class_tree_id, ast09_keep_account_id, to_char(ast09_hold_date,'yyyymmdd')||seq) IN ( SELECT ast09_ast_class_tree_id, ast09_keep_account_id, MAX(to_char(ast09_hold_date,'yyyymmdd')||seq) FROM book1 GROUP BY ast09_ast_class_tree_id, ast09_keep_account_id ) )
SELECT row_number() OVER (ORDER BY act04_account_cd) AS act04_gen_ledger_id , ast09_ast_class_tree_id AS act04_ast_class_tree_id , f_ast_class_tree_nm(ast09_ast_class_tree_id) AS act04_ast_class_tree_nm , act04_account_cd AS act04_account_cd , f_get_account_nm(#{companyId}, act04_account_cd) AS act04_account_nm , SUM(ast09_eval_amt) AS act04_dr_today_diff_amt FROM ( SELECT ast09_ast_class_tree_id , f_get_real_account_code(ast09_company_id, '1100', ast01_item_s_class_cd||COALESCE(ast01_account_type,'')||'00') act04_account_cd , ast09_eval_amt FROM book INNER JOIN ast01_class_tree ON ast01_class_tree_id = ast09_ast_class_tree_id WHERE ( ast01_item_l_class_cd = '10' /* 10:현금 및 예치금 */ OR ast01_item_m_class_cd = '9030' ) /* 9030:선급금 */ AND ast01_asset_type = '1' /* 1:고유자산 */ UNION ALL SELECT act04_ast_class_tree_id , act04_account_cd , (act04_dr_today_bal_amt - act04_cr_today_bal_amt) * -1 FROM act04_gen_ledger INNER JOIN act01_account_code ON ( act01_company_id = act04_company_id AND act01_account_cd = act04_account_cd AND COALESCE(act01_slip_yn,'false') = 'true' ) WHERE act04_company_id = #{companyId} AND act04_std_date = #{holdDate} AND COALESCE(act04_ast_class_tree_id,0) != 0 ) t GROUP BY ast09_ast_class_tree_id, act04_account_cd HAVING SUM(ast09_eval_amt) != 0
) x

SELECT CAST(NULL AS varchar) AS account_code, CAST(NULL AS varchar) AS account_name, x.ast09_ast_class_tree_nm AS ast_class_tree_name, CAST(NULL AS numeric) AS dr_today_bal_amt, CAST(NULL AS numeric) AS cr_today_bal_amt, CAST(NULL AS numeric) AS dr_today_diff_amt, CAST(NULL AS varchar) AS check_code, CAST(NULL AS varchar) AS note, CAST(NULL AS varchar) AS corp_name, CAST(NULL AS varchar) AS corp_code, CAST(NULL AS varchar) AS fund_code, CAST(NULL AS varchar) AS fund_name, CAST(NULL AS numeric) AS icam_fee, CAST(NULL AS numeric) AS for_fee, CAST(NULL AS numeric) AS diff_fee FROM (
WITH book AS ( WITH book1 AS ( SELECT '1' seq , ast09_book.* FROM ast09_book WHERE ast09_company_id = #{companyId} AND (ast09_ast_class_tree_id, ast09_keep_account_id, ast09_hold_date) IN ( SELECT ast09_ast_class_tree_id, ast09_keep_account_id, MAX(ast09_hold_date) FROM ast09_book WHERE ast09_company_id = #{companyId} AND ast09_hold_date <= #{holdDate}
