AND ast09_keep_account_id = #{keepAccountId}
GROUP BY ast09_ast_class_tree_id, ast09_keep_account_id ) UNION ALL SELECT '2' seq , ast11_book_id , ast11_hold_date , ast11_ast_class_tree_id , ast11_keep_account_id , ast11_hold_qty , ast11_pur_amt , ast11_book_amt , ast11_eval_amt , ast11_eval_pl , ast11_first_pur_amt , ast11_first_pur_date , ast11_company_id , ast11_for_pur_amt , ast11_for_book_amt , ast11_for_eval_amt , ast11_for_eval_pl , ast11_fx_pl , ast11_book_end_yn , ast11_acr_int_amt , ast11_for_acr_int_amt , ast11_oci , ast11_for_oci , ast11_lock_up_period_cd , ast11_lock_up_date , ast11_lock_up_qty FROM ast11_book_close WHERE ast11_company_id = #{companyId} AND (ast11_ast_class_tree_id, ast11_keep_account_id, ast11_hold_date) IN ( SELECT ast11_ast_class_tree_id, ast11_keep_account_id, MAX(ast11_hold_date) FROM ast11_book_close WHERE ast11_company_id = #{companyId} AND ast11_hold_date < #{holdDate}
AND ast11_ast_class_tree_id = #{astClassTreeId}
AND ast11_keep_account_id = #{keepAccountId}
GROUP BY ast11_ast_class_tree_id, ast11_keep_account_id ) ) SELECT * FROM book1 WHERE (ast09_ast_class_tree_id, ast09_keep_account_id, to_char(ast09_hold_date,'yyyymmdd')||seq) IN ( SELECT ast09_ast_class_tree_id, ast09_keep_account_id, MAX(to_char(ast09_hold_date,'yyyymmdd')||seq) FROM book1 GROUP BY ast09_ast_class_tree_id, ast09_keep_account_id ) )
SELECT f_ast_class_tree_nm_allpath(ast09_ast_class_tree_id) as ast09_ast_class_tree_nm
FROM book INNER JOIN ast01_class_tree ON ast01_class_tree_id = ast09_ast_class_tree_id WHERE ast01_asset_type = '1' /* 1:고유자산 / 2:운용(펀드)자산 */ AND COALESCE(ast01_item_l_class_cd,'99') = '20' /* 20:증권 */ AND COALESCE(ast09_book_end_yn,'false') != 'true' AND NOT EXISTS ( SELECT 1 FROM ast06_tr INNER JOIN ast08_tr_finance ON ast08_tr_id = ast06_tr_id INNER JOIN act02_journal ON act02_tr_id = ast06_tr_id WHERE ast06_company_id = ast09_company_id AND ast06_ast_class_tree_id = ast09_ast_class_tree_id AND ast08_account_id = ast09_keep_account_id AND ast06_tr_cd IN ('3600','3610') /* (3600:금융상품 평가 / 3610:금융상품 이자평가) */ AND ast06_date = #{holdDate} ) GROUP BY ast01_item_m_class_cd, ast09_ast_class_tree_id ORDER BY ast01_item_m_class_cd, ast09_ast_class_tree_id
) x

SELECT x.act04_account_cd AS account_code, x.act04_account_nm AS account_name, CAST(NULL AS varchar) AS ast_class_tree_name, x.act04_dr_today_bal_amt AS dr_today_bal_amt, x.act04_cr_today_bal_amt AS cr_today_bal_amt, x.act04_dr_today_diff_amt AS dr_today_diff_amt, CAST(NULL AS varchar) AS check_code, CAST(NULL AS varchar) AS note, CAST(NULL AS varchar) AS corp_name, CAST(NULL AS varchar) AS corp_code, CAST(NULL AS varchar) AS fund_code, CAST(NULL AS varchar) AS fund_name, CAST(NULL AS numeric) AS icam_fee, CAST(NULL AS numeric) AS for_fee, CAST(NULL AS numeric) AS diff_fee FROM (
WITH book AS (
WITH book AS ( WITH book1 AS ( SELECT '1' seq , ast09_book.* FROM ast09_book WHERE ast09_company_id = #{companyId} AND (ast09_ast_class_tree_id, ast09_keep_account_id, ast09_hold_date) IN ( SELECT ast09_ast_class_tree_id, ast09_keep_account_id, MAX(ast09_hold_date) FROM ast09_book WHERE ast09_company_id = #{companyId} AND ast09_hold_date <= #{holdDate}
AND ast09_ast_class_tree_id = #{astClassTreeId}
AND ast09_keep_account_id = #{keepAccountId}
GROUP BY ast09_ast_class_tree_id, ast09_keep_account_id ) UNION ALL SELECT '2' seq , ast11_book_id , ast11_hold_date , ast11_ast_class_tree_id , ast11_keep_account_id , ast11_hold_qty , ast11_pur_amt , ast11_book_amt , ast11_eval_amt , ast11_eval_pl , ast11_first_pur_amt , ast11_first_pur_date , ast11_company_id , ast11_for_pur_amt , ast11_for_book_amt , ast11_for_eval_amt , ast11_for_eval_pl , ast11_fx_pl , ast11_book_end_yn , ast11_acr_int_amt , ast11_for_acr_int_amt , ast11_oci , ast11_for_oci , ast11_lock_up_period_cd , ast11_lock_up_date , ast11_lock_up_qty FROM ast11_book_close WHERE ast11_company_id = #{companyId} AND (ast11_ast_class_tree_id, ast11_keep_account_id, ast11_hold_date) IN ( SELECT ast11_ast_class_tree_id, ast11_keep_account_id, MAX(ast11_hold_date) FROM ast11_book_close WHERE ast11_company_id = #{companyId} AND ast11_hold_date < #{holdDate}
AND ast11_ast_class_tree_id = #{astClassTreeId}
AND ast11_keep_account_id = #{keepAccountId}
GROUP BY ast11_ast_class_tree_id, ast11_keep_account_id ) ) SELECT * FROM book1 WHERE (ast09_ast_class_tree_id, ast09_keep_account_id, to_char(ast09_hold_date,'yyyymmdd')||seq) IN ( SELECT ast09_ast_class_tree_id, ast09_keep_account_id, MAX(to_char(ast09_hold_date,'yyyymmdd')||seq) FROM book1 GROUP BY ast09_ast_class_tree_id, ast09_keep_account_id ) )
SELECT account_cd , sum(ast09_eval_amt) as book_amt FROM ( SELECT f_get_real_account_code(ast09_company_id, '1100', ast01_item_s_class_cd||ast01_account_type||'00' ) as account_cd , CASE WHEN COALESCE(ast01_eval_type,'1') = '2' THEN ast09_book_amt ELSE ast09_eval_amt END as ast09_eval_amt FROM book INNER JOIN ast01_class_tree ON ast01_class_tree_id = ast09_ast_class_tree_id WHERE ast01_asset_type = '1' /* 1:고유자산 / 2:운용(펀드)자산 */ AND COALESCE(ast01_item_l_class_cd,'99') = '20' /* 20:증권 */ AND COALESCE(ast09_book_end_yn,'false') != 'true' ) t GROUP BY account_cd ), ledger AS ( SELECT act04_account_cd , (act04_dr_today_bal_amt - act04_cr_today_bal_amt) * CASE WHEN act01_attribute_cd IN ('1','5','9') THEN 1 ELSE -1 END as act04_today_bal_amt FROM act04_gen_ledger INNER JOIN act01_account_code ON ( act01_company_id = act04_company_id AND act01_account_cd = act04_account_cd ) WHERE act04_company_id = #{companyId} AND act04_std_date = #{holdDate} AND ( act01_account_cd LIKE '32%' OR /*(32%:증권)*/ act01_account_cd IN ('3101610100','3101610200') ) /*(3101610100:MMT / 3101610100:CMA)*/ AND COALESCE(act01_slip_yn,'false') = 'true' AND COALESCE(act01_use_yn ,'false') = 'true' ) SELECT row_number() OVER (ORDER BY act04_account_cd) AS act04_gen_ledger_id , act04_account_cd , f_get_account_nm(#{companyId}, act04_account_cd) AS act04_account_nm , act04_dr_today_bal_amt , act04_cr_today_bal_amt , act04_dr_today_diff_amt FROM ( SELECT account_cd AS act04_account_cd , sum(book_amt) AS act04_dr_today_bal_amt , sum(ledger_amt) AS act04_cr_today_bal_amt , sum(book_amt) - sum(ledger_amt) AS act04_dr_today_diff_amt FROM ( SELECT account_cd as account_cd , book_amt as book_amt , 0 as ledger_amt FROM ( SELECT account_cd , book_amt FROM book EXCEPT SELECT act04_account_cd , act04_today_bal_amt FROM ledger ) t UNION ALL SELECT act04_account_cd as account_cd , 0 as book_amt , act04_today_bal_amt as ledger_amt FROM ( SELECT act04_account_cd , act04_today_bal_amt FROM ledger EXCEPT SELECT account_cd , book_amt FROM book ) t ) t2 GROUP BY account_cd ) t3 WHERE act04_dr_today_diff_amt != 0
) x

