AND ast11_ast_class_tree_id = #{astClassTreeId}
AND ast11_keep_account_id = #{keepAccountId}
GROUP BY ast11_ast_class_tree_id, ast11_keep_account_id ) ) SELECT * FROM book1 WHERE (ast09_ast_class_tree_id, ast09_keep_account_id, to_char(ast09_hold_date,'yyyymmdd')||seq) IN ( SELECT ast09_ast_class_tree_id, ast09_keep_account_id, MAX(to_char(ast09_hold_date,'yyyymmdd')||seq) FROM book1 GROUP BY ast09_ast_class_tree_id, ast09_keep_account_id ) )
SELECT ast01_class_tree_nm as ast09_ast_class_tree_nm FROM book INNER JOIN ast01_class_tree ON ast01_class_tree_id = ast09_ast_class_tree_id WHERE ast01_asset_type = '1' /* 1:고유자산 / 2:운용(펀드)자산 */ AND COALESCE(ast01_item_s_class_cd,'999999') = '101005' /* 101005:외화예금 */ AND NOT EXISTS ( SELECT 1 FROM ast06_tr INNER JOIN act02_journal ON act02_tr_id = ast06_tr_id WHERE ast06_company_id = ast09_company_id AND ast06_ast_class_tree_id = ast09_ast_class_tree_id AND ast06_tr_cd = '3700' /* 3700:외화예금 환산평가 */ AND ast06_date = #{holdDate} ) ORDER BY ast01_class_tree_nm collate "ko_KR.utf8" asc
) x

SELECT CAST(NULL AS varchar) AS account_code, CAST(NULL AS varchar) AS account_name, x.ast09_ast_class_tree_nm AS ast_class_tree_name, CAST(NULL AS numeric) AS dr_today_bal_amt, CAST(NULL AS numeric) AS cr_today_bal_amt, CAST(NULL AS numeric) AS dr_today_diff_amt, CAST(NULL AS varchar) AS check_code, CAST(NULL AS varchar) AS note, CAST(NULL AS varchar) AS corp_name, CAST(NULL AS varchar) AS corp_code, CAST(NULL AS varchar) AS fund_code, CAST(NULL AS varchar) AS fund_name, CAST(NULL AS numeric) AS icam_fee, CAST(NULL AS numeric) AS for_fee, CAST(NULL AS numeric) AS diff_fee FROM (
SELECT f_ast_class_tree_nm_allpath(ast13_ast_class_tree_id) as ast09_ast_class_tree_nm FROM ( SELECT * , COALESCE(( SELECT ast16_apply_non_deduct_tax FROM ast16_non_deduct_tax WHERE ast16_pur_tr_id = ast13_pur_tr_id AND ast16_apply_date <= #{holdDate} ORDER BY ast16_apply_date DESC LIMIT 1 ),0) as ast13_non_deduct_tax FROM ast13_book_depn INNER JOIN ast01_class_tree ON ( ast01_class_tree_id = ast13_ast_class_tree_id AND ast01_depn_type IS NOT NULL ) WHERE ast13_company_id = #{companyId} AND COALESCE(ast13_retire_date,'9999-12-31') > #{holdDate} AND (ast13_ast_class_tree_id, ast13_pur_tr_id, ast13_depn_date) IN ( SELECT ast13_ast_class_tree_id, ast13_pur_tr_id, MAX(ast13_depn_date) FROM ast13_book_depn WHERE ast13_company_id = #{companyId} AND ast13_depn_date <= #{holdDate} GROUP BY ast13_ast_class_tree_id, ast13_pur_tr_id ) AND NOT EXISTS ( SELECT 1 FROM ast06_tr INNER JOIN act02_journal ON act02_tr_id = ast06_tr_id WHERE ast06_company_id = ast13_company_id AND ast06_ast_class_tree_id = ast13_ast_class_tree_id AND ast06_pur_tr_id = ast13_pur_tr_id AND ast06_tr_cd = '5012' /* 5012:감가상각 */ AND ast06_date = #{holdDate} ) ) t WHERE ast13_pur_amt + ast13_non_deduct_tax - COALESCE(ast13_acm_depn_cost,0) > 1000 ORDER BY ast01_item_s_class_cd
) x

SELECT CAST(NULL AS varchar) AS account_code, CAST(NULL AS varchar) AS account_name, CAST(NULL AS varchar) AS ast_class_tree_name, x.act04_dr_today_bal_amt AS dr_today_bal_amt, x.act04_cr_today_bal_amt AS cr_today_bal_amt, x.act04_dr_today_diff_amt AS dr_today_diff_amt, CAST(NULL AS varchar) AS check_code, CAST(NULL AS varchar) AS note, CAST(NULL AS varchar) AS corp_name, CAST(NULL AS varchar) AS corp_code, CAST(NULL AS varchar) AS fund_code, CAST(NULL AS varchar) AS fund_name, CAST(NULL AS numeric) AS icam_fee, CAST(NULL AS numeric) AS for_fee, CAST(NULL AS numeric) AS diff_fee FROM (
SELECT row_number() OVER () AS act04_gen_ledger_id , remDepnCost AS act04_dr_today_bal_amt , act04_today_bal_amt AS act04_cr_today_bal_amt , remDepnCost - act04_today_bal_amt AS act04_dr_today_diff_amt FROM ( SELECT COALESCE(( SELECT SUM( ast13_pur_amt - COALESCE(ast13_acm_depn_cost,0) + COALESCE(( SELECT ast16_apply_non_deduct_tax FROM ast16_non_deduct_tax WHERE ast16_pur_tr_id = ast13_pur_tr_id AND ast16_apply_date <= #{holdDate} ORDER BY ast16_apply_date DESC LIMIT 1 ),0) ) FROM ast13_book_depn INNER JOIN ast01_class_tree ON ast01_class_tree_id = ast13_ast_class_tree_id WHERE ast13_company_id = #{companyId} AND (ast13_pur_tr_id, ast13_depn_date) IN ( SELECT ast13_pur_tr_id, MAX(ast13_depn_date) FROM ast13_book_depn WHERE ast13_company_id = #{companyId} AND ast13_depn_date <= #{holdDate} GROUP BY ast13_pur_tr_id ) AND COALESCE(ast13_retire_date,'9999-12-31') > #{holdDate} AND COALESCE(ast01_item_l_class_cd,'99') = '50' /*(50:유형자산)*/ ),0) as remDepnCost , COALESCE(( SELECT SUM((act04_dr_today_bal_amt - act04_cr_today_bal_amt) * CASE WHEN act01_attribute_cd IN ('1','5','9') THEN 1 ELSE -1 END) FROM act04_gen_ledger INNER JOIN act01_account_code ON ( act01_company_id = act04_company_id AND act01_account_cd = act04_account_cd ) WHERE act04_company_id = #{companyId} AND act04_std_date = #{holdDate} AND act01_account_cd = '3500000000' /*(3500000000:유형자산)*/ AND COALESCE(act01_use_yn ,'false') = 'true' ),0) as act04_today_bal_amt ) t WHERE remDepnCost != act04_today_bal_amt
) x

SELECT CAST(NULL AS varchar) AS account_code, CAST(NULL AS varchar) AS account_name, CAST(NULL AS varchar) AS ast_class_tree_name, x.act04_dr_today_bal_amt AS dr_today_bal_amt, x.act04_cr_today_bal_amt AS cr_today_bal_amt, x.act04_dr_today_diff_amt AS dr_today_diff_amt, CAST(NULL AS varchar) AS check_code, CAST(NULL AS varchar) AS note, CAST(NULL AS varchar) AS corp_name, CAST(NULL AS varchar) AS corp_code, CAST(NULL AS varchar) AS fund_code, CAST(NULL AS varchar) AS fund_name, CAST(NULL AS numeric) AS icam_fee, CAST(NULL AS numeric) AS for_fee, CAST(NULL AS numeric) AS diff_fee FROM (
SELECT row_number() OVER () AS act04_gen_ledger_id , book_amt AS act04_dr_today_bal_amt , account_amt AS act04_cr_today_bal_amt , book_amt - account_amt AS act04_dr_today_diff_amt FROM ( SELECT COALESCE(( SELECT SUM(ast13_pur_amt) FROM ast13_book_depn INNER JOIN ast01_class_tree ON ast01_class_tree_id = ast13_ast_class_tree_id WHERE ast13_company_id = #{companyId} AND (ast13_pur_tr_id, ast13_depn_date) IN ( SELECT ast13_pur_tr_id, MAX(ast13_depn_date) FROM ast13_book_depn WHERE ast13_company_id = #{companyId} AND ast13_depn_date <= #{holdDate} GROUP BY ast13_pur_tr_id ) AND COALESCE(ast13_retire_date,'9999-12-31') > #{holdDate} AND COALESCE(ast01_item_s_class_cd,'99') = '952002' /*(952002:소모품-비품)*/ AND TO_CHAR(ast13_pur_date,'yyyy') = TO_CHAR(#{holdDate}::date,'yyyy') ),0) as book_amt , COALESCE(( SELECT SUM((act04_dr_today_bal_amt - act04_cr_today_bal_amt) * CASE WHEN act01_attribute_cd IN ('1','5','9') THEN 1 ELSE -1 END) FROM act04_gen_ledger INNER JOIN act01_account_code ON ( act01_company_id = act04_company_id AND act01_account_cd = act04_account_cd ) WHERE act04_company_id = #{companyId} AND act04_std_date = #{holdDate} AND act01_account_cd = ( SELECT act13_real_account_cd FROM act13_real_account_map WHERE act13_company_id = act04_company_id AND act13_repr_account_cd = '5802' /*(5802:소모품비계정)*/ AND act13_account_map LIKE '952002%' /*(952002%:소모품_비품)*/ ) AND COALESCE(act01_use_yn ,'false') = 'true' ),0) as account_amt ) t WHERE book_amt != account_amt
) x

SELECT x.act04_account_cd AS account_code, x.act04_account_nm AS account_name, CAST(NULL AS varchar) AS ast_class_tree_name, x.act04_dr_today_bal_amt AS dr_today_bal_amt, x.act04_cr_today_bal_amt AS cr_today_bal_amt, x.act04_dr_today_diff_amt AS dr_today_diff_amt, CAST(NULL AS varchar) AS check_code, CAST(NULL AS varchar) AS note, CAST(NULL AS varchar) AS corp_name, CAST(NULL AS varchar) AS corp_code, CAST(NULL AS varchar) AS fund_code, CAST(NULL AS varchar) AS fund_name, CAST(NULL AS numeric) AS icam_fee, CAST(NULL AS numeric) AS for_fee, CAST(NULL AS numeric) AS diff_fee FROM (
WITH book AS ( SELECT account_cd , SUM(rem_depn_cost) as rem_depn_cost FROM ( SELECT f_get_real_account_code(ast13_company_id, '1100', ast01_item_s_class_cd||ast01_account_type||'00' ) as account_cd , ast13_pur_amt - COALESCE(ast13_acm_depn_cost,0) + COALESCE(( SELECT ast16_apply_non_deduct_tax FROM ast16_non_deduct_tax WHERE ast16_pur_tr_id = ast13_pur_tr_id AND ast16_apply_date <= #{holdDate} ORDER BY ast16_apply_date DESC LIMIT 1 ),0) as rem_depn_cost FROM ast13_book_depn INNER JOIN ast01_class_tree ON ast01_class_tree_id = ast13_ast_class_tree_id WHERE ast13_company_id = #{companyId} AND (ast13_pur_tr_id, ast13_depn_date) IN ( SELECT ast13_pur_tr_id, MAX(ast13_depn_date) FROM ast13_book_depn WHERE ast13_company_id = #{companyId} AND ast13_depn_date <= #{holdDate} GROUP BY ast13_pur_tr_id ) AND COALESCE(ast13_retire_date,'9999-12-31') > #{holdDate} AND COALESCE(ast01_item_l_class_cd,'99') = '55' /*(55:무형자산)*/ ) t GROUP BY account_cd ), ledger AS ( SELECT act04_account_cd , (act04_dr_today_bal_amt - act04_cr_today_bal_amt) * CASE WHEN act01_attribute_cd IN ('1','5','9') THEN 1 ELSE -1 END as act04_today_bal_amt FROM act04_gen_ledger INNER JOIN act01_account_code ON ( act01_company_id = act04_company_id AND act01_account_cd = act04_account_cd ) WHERE act04_company_id = #{companyId} AND act04_std_date = #{holdDate} AND act01_account_cd LIKE '3812%' /*(3812% : 무형자산)*/ AND COALESCE(act01_slip_yn,'false') = 'true' AND COALESCE(act01_use_yn ,'false') = 'true' ) SELECT row_number() OVER (ORDER BY account_cd) AS act04_gen_ledger_id , account_cd AS act04_account_cd , f_get_account_nm(#{companyId}, account_cd) AS act04_account_nm , sum(rem_depn_cost) AS act04_dr_today_bal_amt , sum(ledger_amt) AS act04_cr_today_bal_amt , sum(rem_depn_cost) - sum(ledger_amt) AS act04_dr_today_diff_amt FROM ( SELECT account_cd as account_cd , rem_depn_cost as rem_depn_cost , 0 as ledger_amt FROM ( SELECT account_cd , rem_depn_cost FROM book EXCEPT SELECT act04_account_cd , act04_today_bal_amt FROM ledger ) t UNION ALL SELECT act04_account_cd as account_cd , 0 as rem_depn_cost , act04_today_bal_amt as ledger_amt FROM ( SELECT act04_account_cd , act04_today_bal_amt FROM ledger EXCEPT SELECT account_cd , rem_depn_cost FROM book ) t ) t2 GROUP BY account_cd
) x

SELECT CAST(NULL AS varchar) AS account_code, CAST(NULL AS varchar) AS account_name, CAST(NULL AS varchar) AS ast_class_tree_name, CAST(NULL AS numeric) AS dr_today_bal_amt, CAST(NULL AS numeric) AS cr_today_bal_amt, CAST(NULL AS numeric) AS dr_today_diff_amt, CAST(NULL AS varchar) AS check_code, x.act04_note AS note, CAST(NULL AS varchar) AS corp_name, CAST(NULL AS varchar) AS corp_code, CAST(NULL AS varchar) AS fund_code, CAST(NULL AS varchar) AS fund_name, CAST(NULL AS numeric) AS icam_fee, CAST(NULL AS numeric) AS for_fee, CAST(NULL AS numeric) AS diff_fee FROM (
SELECT '전표발생일:'||to_char(act02_date,'yyyy.mm.dd')||' / ' ||'전표번호:'||act02_journal_no||' / ' ||'계정과목:'||CASE WHEN COALESCE(act01_use_yn,'false') = 'false' THEN '(사용X)' ELSE '' END||act01_account_nm ||'('||act01_account_cd||')' as act04_note FROM act02_journal INNER JOIN act03_journal_dtl ON act03_journal_id = act02_journal_id INNER JOIN act01_account_code ON ( act01_company_id = act02_company_id AND act01_account_cd IN (act03_dr_account_cd, act03_cr_account_cd) ) WHERE act02_company_id = #{companyId} AND act02_date BETWEEN #{startDate} AND #{closeDate} AND COALESCE(act01_slip_yn,'false') != 'true' ORDER BY act02_date, act02_journal_no, act01_account_cd
) x

SELECT CAST(NULL AS varchar) AS account_code, CAST(NULL AS varchar) AS account_name, CAST(NULL AS varchar) AS ast_class_tree_name, CAST(NULL AS numeric) AS dr_today_bal_amt, CAST(NULL AS numeric) AS cr_today_bal_amt, CAST(NULL AS numeric) AS dr_today_diff_amt, CAST(NULL AS varchar) AS check_code, x.act04_note AS note, CAST(NULL AS varchar) AS corp_name, CAST(NULL AS varchar) AS corp_code, CAST(NULL AS varchar) AS fund_code, CAST(NULL AS varchar) AS fund_name, CAST(NULL AS numeric) AS icam_fee, CAST(NULL AS numeric) AS for_fee, CAST(NULL AS numeric) AS diff_fee FROM (
SELECT '미사용 계정과목 : '||CASE WHEN COALESCE(act01_use_yn,'false') = 'false' THEN '(사용X)' ELSE '' END||act01_account_nm ||'('||act01_account_cd||')' as act04_note FROM act04_gen_ledger INNER JOIN act01_account_code ON ( act01_company_id = act04_company_id AND act01_account_cd = act04_account_cd ) WHERE act04_company_id = #{companyId} AND act04_std_date = #{closeDate} AND COALESCE(act01_use_yn,'false') = 'false' AND (act04_dr_today_bal_amt - act04_cr_today_bal_amt) != 0
) x

SELECT CAST(NULL AS varchar) AS account_code, CAST(NULL AS varchar) AS account_name, CAST(NULL AS varchar) AS ast_class_tree_name, CAST(NULL AS numeric) AS dr_today_bal_amt, CAST(NULL AS numeric) AS cr_today_bal_amt, CAST(NULL AS numeric) AS dr_today_diff_amt, CAST(NULL AS varchar) AS check_code, x.act04_note AS note, CAST(NULL AS varchar) AS corp_name, CAST(NULL AS varchar) AS corp_code, CAST(NULL AS varchar) AS fund_code, CAST(NULL AS varchar) AS fund_name, CAST(NULL AS numeric) AS icam_fee, CAST(NULL AS numeric) AS for_fee, CAST(NULL AS numeric) AS diff_fee FROM (
SELECT CONCAT('전표번호:'||act02_journal_no||' / ' ,f_cdnm('trCode', f_get_journal_tr_cd(act02_journal_id), act02_company_id, act02_date)) as act04_note FROM act02_journal INNER JOIN act03_journal_dtl ON act03_journal_id = act02_journal_id WHERE act02_company_id = #{companyId} AND act02_date BETWEEN #{startDate} AND #{closeDate} AND ( ( act03_dr_account_cd IS NULL AND COALESCE(act03_dr_for_amt, 0) != 0 ) OR ( act03_cr_account_cd IS NULL AND COALESCE(act03_cr_for_amt, 0) != 0 ) ) ORDER BY act02_journal_no
) x

SELECT CAST(NULL AS varchar) AS account_code, CAST(NULL AS varchar) AS account_name, CAST(NULL AS varchar) AS ast_class_tree_name, CAST(NULL AS numeric) AS dr_today_bal_amt, CAST(NULL AS numeric) AS cr_today_bal_amt, CAST(NULL AS numeric) AS dr_today_diff_amt, CAST(NULL AS varchar) AS check_code, x.ast30_note AS note, x.ast30_corp_nm AS corp_name, x.ast30_corp_cd AS corp_code, x.ast30_fund_cd AS fund_code, x.ast30_fund_nm AS fund_name, x.ast30_icam_fee AS icam_fee, x.ast30_for_fee AS for_fee, x.ast30_diff_fee AS diff_fee FROM (
WITH ast33 AS ( SELECT ast33_fund_trans.* , sys15_corp_cd as ast33_corp_cd FROM ast33_fund_trans INNER JOIN sys15_corp ON sys15_corp_id = ast33_corp_id INNER JOIN icam10_fee ON ( icam10_company_id = ast33_company_id AND icam10_icam_company_cd = sys15_corp_cd AND icam10_fund_cd = ast33_fund_cd AND icam10_rmk_cd = 'P00' AND icam10_std_date = #{closeDate} ) WHERE ast33_company_id = #{companyId} AND ast33_fund_trans_cd = '2' /*(2:이관(입))*/ AND ast33_date > icam10_bf_pay_date ) , biz17 AS ( SELECT biz17_dual_manage_fund.* , sys15_corp_cd as biz17_corp_cd FROM biz17_dual_manage_fund INNER JOIN biz13_with_corp ON biz13_cont_corp_id = biz17_cont_corp_id INNER JOIN sys15_corp ON sys15_corp_id = biz13_corp_id WHERE biz17_company_id = #{companyId} AND biz17_start_date BETWEEN date_trunc('month',#{closeDate}::date)::date AND #{closeDate}::date AND biz13_manage_type = '1' /*(1:자산운용)*/ ) , icam AS ( SELECT icam12_icam_company_cd , icam12_fund_cd , icam12_fund_nm , CASE WHEN EXISTS ( SELECT 1 FROM ast33 WHERE ast33_corp_cd = icam12_icam_company_cd AND ast33_fund_cd = icam12_fund_cd UNION ALL SELECT 2 FROM biz17 WHERE biz17_corp_cd = icam12_icam_company_cd AND biz17_fund_cd = icam12_fund_cd ) THEN ( SELECT SUM(f_calc_dual_fund_fee( icam10_company_id , icam10_icam_company_cd , icam10_fund_cd , icam10_std_date , icam10_fee ) * CASE WHEN icam10_drcr_type = 'C' THEN 1 ELSE -1 END) FROM icam10_fee WHERE icam10_company_id = icam12_company_id AND icam10_icam_company_cd = icam12_icam_company_cd AND icam10_fund_cd = icam12_fund_cd AND icam10_rmk_cd IN ('P00','D20','D30') /* (P00:보수 및 수수료(비용)발생 / D20:보수인출 / D30:해지금/보수인출) */ AND icam10_std_date BETWEEN date_trunc('month',#{closeDate}::date)::date AND #{closeDate}::date ) + COALESCE(ast30_for_fee,0) ELSE f_calc_dual_fund_fee( icam12_company_id , icam12_icam_company_cd , icam12_fund_cd , icam12_std_date , icam12_for_fee ) END as icam12_for_fee , f_calc_dual_fund_fee( icam12_company_id , icam12_icam_company_cd , icam12_fund_cd , icam12_std_date , icam12_for_fee ) as icam12_for_fee2 FROM icam12_fee_book LEFT JOIN ( SELECT sys15_corp_cd , ast30_fund_cd , ast30_for_fee FROM ast30_book_fund_fee INNER JOIN sys15_corp ON sys15_corp_id = ast30_corp_id WHERE ast30_company_id = #{companyId} AND ast30_hold_date = (date_trunc('month', #{closeDate}::date) + interval '-1day')::date ) t ON ( sys15_corp_cd = icam12_icam_company_cd AND ast30_fund_cd = icam12_fund_cd ) WHERE icam12_company_id = #{companyId} AND icam12_std_date = #{closeDate} ) , erp AS ( SELECT * FROM ast30_book_fund_fee INNER JOIN sys15_corp ON sys15_corp_id = ast30_corp_id WHERE ast30_company_id = #{companyId} AND ast30_hold_date = #{closeDate} ) SELECT row_number() OVER (ORDER BY company_cd, fund_cd) as ast30_book_fund_fee_id , company_cd as ast30_corp_cd , sys15_corp_nm as ast30_corp_nm , fund_cd as ast30_fund_cd , fund_nm as ast30_fund_nm , icam_fee as ast30_icam_fee , ast_fee as ast30_for_fee , CASE WHEN icam_fee != ast_fee THEN icam_fee ELSE icam_fee2 END - ast_fee as ast30_diff_fee , note as ast30_note FROM ( SELECT DISTINCT * FROM ( /*================== ICAM = AssetERP(+) ====================== */ SELECT icam12_icam_company_cd as company_cd , icam12_fund_cd as fund_cd , icam12_fund_nm as fund_nm , icam12_for_fee as icam_fee , icam12_for_fee2 as icam_fee2 , COALESCE(ast30_for_fee, 0) as ast_fee , CASE WHEN ast30_fund_cd IS NULL THEN ' (AssetERP 정보 미존재)' ELSE '' END as note FROM icam LEFT JOIN erp ON ( sys15_corp_cd = icam12_icam_company_cd AND ast30_fund_cd = icam12_fund_cd ) WHERE icam12_for_fee != COALESCE(ast30_for_fee, 0) AND icam12_for_fee2 != COALESCE(ast30_for_fee, 0) /*==================== AssetERP = ICAM(+) ======================*/ UNION ALL SELECT sys15_corp_cd as company_cd , ast30_fund_cd as fund_cd , ast30_fund_nm as fund_nm , COALESCE(icam12_for_fee , 0) as icam_fee , COALESCE(icam12_for_fee2, 0) as icam_fee2 , ast30_for_fee as ast_fee , CASE WHEN icam12_fund_cd IS NULL THEN ' (ICAM 정보 미존재)' ELSE '' END as note FROM erp LEFT JOIN icam ON ( icam12_icam_company_cd = sys15_corp_cd AND icam12_fund_cd = ast30_fund_cd ) WHERE ast30_for_fee != COALESCE(icam12_for_fee , 0) AND ast30_for_fee != COALESCE(icam12_for_fee2, 0) ) t ) tt LEFT JOIN sys15_corp ON ( sys15_company_id = #{companyId} AND sys15_corp_cd = company_cd AND sys15_use_yn = 'true' )
) x

SELECT CAST(NULL AS varchar) AS account_code, CAST(NULL AS varchar) AS account_name, CAST(NULL AS varchar) AS ast_class_tree_name, CAST(NULL AS numeric) AS dr_today_bal_amt, CAST(NULL AS numeric) AS cr_today_bal_amt, CAST(NULL AS numeric) AS dr_today_diff_amt, CAST(NULL AS varchar) AS check_code, x.ast30_note AS note, x.ast30_corp_nm AS corp_name, x.ast30_corp_cd AS corp_code, x.ast30_fund_cd AS fund_code, x.ast30_fund_nm AS fund_name, x.ast30_icam_fee AS icam_fee, x.ast30_for_fee AS for_fee, x.ast30_diff_fee AS diff_fee FROM (
SELECT row_number() OVER (ORDER BY company_cd, fund_cd) as ast30_book_fund_fee_id , company_cd as ast30_corp_cd , '' as ast30_corp_nm , fund_cd as ast30_fund_cd , fund_nm as ast30_fund_nm , icam_fee as ast30_icam_fee , ast_fee as ast30_for_fee , icam_fee - ast_fee as ast30_diff_fee , note as ast30_note FROM ( SELECT DISTINCT * FROM ( /*================== ICAM = AssetERP(+) ====================== */ SELECT icam12_icam_company_cd as company_cd , icam12_fund_cd as fund_cd , icam12_fund_nm as fund_nm , icam12_for_fee as icam_fee , COALESCE(ast30_for_fee, 0) as ast_fee , CASE WHEN ast30_fund_cd IS NULL THEN ' (AssetERP 정보 미존재)' ELSE '' END as note FROM icam12_fee_book LEFT OUTER JOIN ast30_book_fund_fee ON ( ast30_company_id = icam12_company_id AND ast30_hold_date = icam12_std_date AND ast30_fund_cd = icam12_fund_cd ) WHERE icam12_company_id = #{companyId} AND icam12_std_date = #{closeDate} AND icam12_for_fee != COALESCE(ast30_for_fee, 0) UNION ALL /*==================== AssetERP = ICAM(+) ======================*/ SELECT ( SELECT sys01_icam_company_cd FROM sys01_company WHERE sys01_company_id = ast30_company_id ) as company_cd , ast30_fund_cd as fund_cd , ast30_fund_nm as fund_nm , COALESCE(icam12_for_fee, 0) as icam_fee , ast30_for_fee as ast_fee , CASE WHEN icam12_fund_cd IS NULL THEN ' (ICAM 정보 미존재)' ELSE '' END as note FROM ast30_book_fund_fee LEFT OUTER JOIN icam12_fee_book ON ( icam12_company_id = ast30_company_id AND icam12_std_date = ast30_hold_date AND icam12_fund_cd = ast30_fund_cd ) WHERE ast30_company_id = #{companyId} AND ast30_hold_date = #{closeDate} AND ast30_for_fee != COALESCE(icam12_for_fee, 0) ) t ) tt
) x

SELECT CAST(NULL AS varchar) AS account_code, CAST(NULL AS varchar) AS account_name, CAST(NULL AS varchar) AS ast_class_tree_name, CAST(NULL AS numeric) AS dr_today_bal_amt, CAST(NULL AS numeric) AS cr_today_bal_amt, CAST(NULL AS numeric) AS dr_today_diff_amt, CAST(NULL AS varchar) AS check_code, CAST(NULL AS varchar) AS note, x.ast30_corp_nm AS corp_name, CAST(NULL AS varchar) AS corp_code, CAST(NULL AS varchar) AS fund_code, CAST(NULL AS varchar) AS fund_name, CAST(NULL AS numeric) AS icam_fee, CAST(NULL AS numeric) AS for_fee, CAST(NULL AS numeric) AS diff_fee FROM (
SELECT row_number() OVER (ORDER BY sys15_corp_nm) as ast30_book_fund_fee_id , sys15_corp_nm||'('||sys15_corp_cd||') '||count(*)||'건' as ast30_corp_nm FROM ast30_book_fund_fee LEFT OUTER JOIN sys15_corp ON sys15_corp_id = ast30_corp_id LEFT OUTER JOIN ast31_book_fund_fee_close ON ast31_book_fund_fee_id = ast30_book_fund_fee_id WHERE ast30_company_id = #{companyId} AND ast30_hold_date = #{closeDate} AND ast31_book_fund_fee_close_id IS NULL GROUP BY sys15_corp_cd, sys15_corp_nm
) x

